installation.script:
#!/bin/ash
apk add --no-cache git go ca-certificates

cd /mnt/server

mkdir -p .cache/go .cache/gocache .cache/tmp
export GOPATH="/mnt/server/.cache/go"
export GOCACHE="/mnt/server/.cache/gocache"
export GOTMPDIR="/mnt/server/.cache/tmp"
export CGO_ENABLED=0

if [ -d .git ]; then
    echo "[Installer] Repository already exists. Pulling latest commits..."
    git pull
else
    echo "[Installer] Cloning repository ${GIT_REPO} (${GIT_BRANCH})..."
    git clone --single-branch --branch ${GIT_BRANCH} ${GIT_REPO} .
fi

echo "[Installer] Compiling Go binary..."
go build -ldflags="-s -w" -o ${SERVER_BINARY} ./cmd/server
rm -rf .cache
chmod +x ${SERVER_BINARY}

if [ ! -f .env ]; then
    cat << 'EOF' > .env
PORT=${SERVER_PORT}
API_KEYS=${API_KEYS}
ALLOWED_DOMAIN=${ALLOWED_DOMAIN}
DATABASE_URL=${DATABASE_URL}
REDIS_URL=${REDIS_URL}
LEGACY_MODE=${LEGACY_MODE}
USER_CACHE_TTL=${USER_CACHE_TTL}
NEGATIVE_CACHE_TTL=${NEGATIVE_CACHE_TTL}
AVATAR_CACHE_TTL=${AVATAR_CACHE_TTL}
AVATAR_SIZE=${AVATAR_SIZE}
AVATAR_QUALITY=${AVATAR_QUALITY}
DB_MAX_OPEN_CONNS=${DB_MAX_OPEN_CONNS}
DB_MAX_IDLE_CONNS=${DB_MAX_IDLE_CONNS}
DB_CONN_MAX_LIFETIME=${DB_CONN_MAX_LIFETIME}
DB_CONN_MAX_IDLE_TIME=${DB_CONN_MAX_IDLE_TIME}
LOG_LEVEL=${LOG_LEVEL}
EOF
fi

echo "-----------------------------------------"
echo "Build & Installation completed! Binary: ${SERVER_BINARY}"
echo "-----------------------------------------"
